import React from 'react';
import { products } from '../mockData';

const ProductsSection = () => {
  return (
    <section className="py-20 bg-gray-100">
      <div className="container mx-auto px-4">
        <h2 className="text-center text-3xl font-light text-gray-600 tracking-[0.2em] mb-16">
          OUR PRODUCTS
        </h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {products.map((product) => (
            <div
              key={product.id}
              className="group relative overflow-hidden rounded-lg shadow-lg hover:shadow-2xl transition-all duration-300"
            >
              {/* Product Image */}
              <div className="relative h-80 overflow-hidden">
                <img
                  src={product.image}
                  alt={product.name}
                  className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-60"></div>
              </div>
              
              {/* Product Info Overlay */}
              <div className="absolute bottom-0 left-0 right-0 p-6 text-white">
                <p className="text-xs tracking-[0.2em] mb-2 text-[#f4d03f]">
                  {product.category}
                </p>
                <h3 className="text-2xl font-light mb-2">{product.name}</h3>
                {product.description && (
                  <p className="text-sm text-gray-200 mb-2">{product.description}</p>
                )}
                {product.sizeRange && (
                  <p className="text-sm font-semibold text-black bg-[#f4d03f] inline-block px-3 py-1 rounded">
                    {product.sizeRange}
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default ProductsSection;
